# Python program to find all permutations of a string
# by fixing one character and permuting the rest

def permute(s):
    if len(s) <= 1:
        return [s]
    result = []
    for i in range(len(s)):
        rest = s[:i] + s[i + 1:]
        for p in permute(rest):
            result.append(s[i] + p)
    return result

# Driver code
