    for p in permute("abc"):
        print(p)

# Python program to print all permutations of a list
# using Heap's algorithm

def heap_permutation(a, size, n):
    if size == 1:
        print(a)
        return
    for i in range(size):
        heap_permutation(a, size - 1, n)
        if size % 2 == 1:
            a[0], a[size - 1] = a[size - 1], a[0]
        else:
            a[i], a[size - 1] = a[size - 1], a[i]

# Driver code
if __name__ == "__main__":
    a = [1, 2, 3]
    n = len(a)
    heap_permutation(a, n, n)

# Python program to print all permutations of a list
# by repeatedly calling next_permutation

def next_permutation(a):
    i = len(a) - 2
    while i >= 0 and a[i] >= a[i + 1]:
        i -= 1
    if i < 0:
        return False
    j = len(a) - 1
    while a[j] <= a[i]:
        j -= 1
    a[i], a[j] = a[j], a[i]
    a[i + 1:] = reversed(a[i + 1:])
    return True

# Driver code
if __name__ == "__main__":
    a = [1, 2, 3, 4]
    print(a)
    while next_permutation(a):
        print(a)

# Python program to sort an array by trying every
# permutation until a sorted one is found

def is_sorted(a):
    for i in range(len(a) - 1):
        if a[i] > a[i + 1]:
            return False
    return True

def permutation_sort(a, l):
    if l == len(a) - 1:
        return is_sorted(a)
    for i in range(l, len(a)):
        a[l], a[i] = a[i], a[l]
        if permutation_sort(a, l + 1):
            return True
        a[l], a[i] = a[i], a[l]
    return False

# Driver code
if __name__ == "__main__":
    a = [3, 1, 2]
    permutation_sort(a, 0)
    print(a)

# Python program to count derangements of 0..n-1 by
# generating every permutation and rejecting fixed points

def count_derangements(a, l, n):
    if l == n:
        for i in range(n):
            if a[i] == i:
                return 0
        return 1
    count = 0
    for i in range(l, n):
        a[l], a[i] = a[i], a[l]
        count += count_derangements(a, l + 1, n)
        a[l], a[i] = a[i], a[l]
    return count

